-- Fictional clubs, players, accounts, banners, notifications and contact-change requests for the Player's own writes
-- characterization (/api/me/* writes and POST /api/account/contact-change). Applied on top of the Prisma migrations.
-- Generated by apps/api/testdata/tools/gen-writes-player-cases.py: edit that, not this. The player accounts are 'rotra' with a
-- sign-in identity (auth_identities, id = the account's auth_subject, login key = the contact email) because the TypeScript
-- side mocks the session and the Go side has no Supabase. Foreign key checks and triggers are off for this load. The file is
-- also the reset between cases, so it removes what it inserts.
BEGIN;
SET LOCAL session_replication_role = replica;

DELETE FROM session_slot_transfers; DELETE FROM session_players; DELETE FROM player_notifications; DELETE FROM admin_audit_events; DELETE FROM player_social_links;
DELETE FROM player_contact_change_requests; DELETE FROM club_players; DELETE FROM shared_player_entries;
DELETE FROM player_accounts; DELETE FROM player_private_contacts; DELETE FROM player_id_allocations; DELETE FROM player_id_counters;
DELETE FROM players; DELETE FROM club_accounts; DELETE FROM clubs; DELETE FROM profile_banners; DELETE FROM feature_flags;
DELETE FROM admin_accounts;
DELETE FROM player_claim_links; DELETE FROM club_player_claim_links; DELETE FROM club_player_private_inputs; DELETE FROM session_publications; DELETE FROM queue_sessions;
DELETE FROM auth_events WHERE audience = 'player'; DELETE FROM auth_sessions WHERE audience = 'player'; DELETE FROM auth_identities WHERE audience = 'player' OR id IN ('f5000000-0000-4000-8000-000000000001', 'f5000000-0000-4000-8000-000000000002');




-- Smash Club's code has a letter that JavaScript upper-cases to two (the sharp s): 'smashß123' reads as SMASHSS123. Net Ninjas
-- has a code and no members; Beta has none.

UPDATE players SET experience_months = 30, experience_recorded_at = TIMESTAMPTZ '2026-05-20 00:00:00+00', personal_details = '{"playingStyle":"Aggressive net player"}'::jsonb, details_version = 1 WHERE id = 'd4000000-0000-4000-8000-000000000001';
UPDATE players SET experience_months = 5, experience_recorded_at = TIMESTAMPTZ '2026-11-01 00:00:00+00', personal_details = '{"playingStyle":7}'::jsonb, details_version = 1 WHERE id = 'd4000000-0000-4000-8000-000000000002';
-- Alice's Google email is her ROTRA email and she has a phone: three of three, verified, so she has no reminder. Bob has none
-- of them (the reminder is unread); Dan has marked it read; Carla has Google but not the email.


-- Alice and Dan are saved by Smash Club; Dan also has a row he left at Birdie Club.

-- Alice's last Admin edit while claimed: the note her own profile shows.

-- Dan: inside the 90-day window (it starts 2026-08-22 04:00 UTC), exactly at its edge, outside it, read and unread. Bob and
-- Alice have one unread each; Eve's is read.

-- Hal has a request open (and its command id is Hal's), Carla one that is pending.

-- Sign-in identities of the player accounts (login key = the contact email). Carla's has no password (an account made with
-- Google). Everyone else's has one.
SELECT a.auth_subject, 'player', lower(coalesce(c.email, 'login-' || a.player_id::text)), CASE WHEN a.player_id = 'd4000000-0000-4000-8000-000000000003' THEN '' ELSE 'fake-hash-for-tests' END, 'argon2id', TIMESTAMPTZ '2026-11-01 00:00:00+00', TIMESTAMPTZ '2026-11-01 00:00:00+00', TIMESTAMPTZ '2026-11-01 00:00:00+00', 1
FROM player_accounts a LEFT JOIN player_private_contacts c ON c.player_id = a.player_id;

COMMIT;
